from __future__ import annotations
import base64, shutil
from datetime import datetime
from pathlib import Path

TARGET="alliance_exception_forensics_v424.py"
REG="alliance_optional_property_modules.py"
DATA=""

def chk(p):
    compile(p.read_text(encoding="utf-8"), str(p), "exec")

def main():
    r=Path.cwd()
    required=[
        "alliance_exception_forensics_v424.py",
        "alliance_automation_grammar_rescue_v423.py",
        "alliance_automation_closure_v422.py",
        "alliance_automation_truth_escalator_v421.py",
        "alliance_automation_machine_v420.py",
        "alliance_cre_championship_v410.py",
        "alliance_cre_academy_v402.py",
        REG,
    ]
    missing=[x for x in required if not (r/x).exists()]
    if missing:
        raise SystemExit("Missing cumulative files: "+", ".join(missing))

    current=(r/TARGET).read_text(encoding="utf-8")
    if "a.evidence a_evidence" not in current and "a.consensus a_evidence" not in current:
        raise SystemExit("Unexpected v424 source shape. Refusing blind overwrite.")

    backup=r/f"{TARGET}.before-hotfix-{datetime.now().strftime('%Y%m%d-%H%M%S')}.bak"
    shutil.copy2(r/TARGET, backup)
    (r/TARGET).write_text(base64.b64decode(DATA).decode(), encoding="utf-8")

    chk(r/TARGET)
    chk(r/REG)

    text421=(r/"alliance_automation_truth_escalator_v421.py").read_text(encoding="utf-8")
    if "consensus JSONB" not in text421:
        raise SystemExit("v421 schema verification failed: consensus column not found.")
    if "a.consensus a_evidence" not in (r/TARGET).read_text(encoding="utf-8"):
        raise SystemExit("Hotfix verification failed.")

    print("Foundation 4.2.4.1 hotfix installed")
    print("Fixed: v421 truth uses consensus JSONB, not evidence JSONB")
    print("No database mutation required")
    print("Frozen V4 student unchanged")
    print("Production/WhatsApp/Gold writes: 0")
    print("Dashboard remains: /property-brain/automation-v424")
    print("Backup:", backup)

if __name__=="__main__":
    main()
